template <bool B>
inline bool VerifyCommandBody(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, CommandBody type) {
  switch (type) {
    case CommandBody_NONE: {
      return true;
    }
    case CommandBody_SetMode: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::SetMode *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_SetState: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::SetState *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_Mdi: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::Mdi *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_SetTeleop: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::SetTeleop *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_Home: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::Home *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_JogStop: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::JogStop *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_SetJog: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::SetJog *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_SelectProgram: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::SelectProgram *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_SetView: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::SetView *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_Answer: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::Answer *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_AskOperator: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::AskOperator *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_ClaimFocus: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::ClaimFocus *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody_Abort: {
      auto ptr = reinterpret_cast<const linuxcnc::protocol::Abort *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyCommandBodyVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyCommandBody(
        verifier,  values->Get(i), types->GetEnum<CommandBody>(i))) {
      return false;
    }
  }
  return true;
}

